SELECT id, check_user_id, check_user_name, check_user_department_id, check_user_department_name,
       coop_user_id, coop_user_name, check_data_id, gmt_create_time, check_result
FROM tb_static_photo_check
WHERE gmt_create_time >= #{startTime} AND gmt_create_time < #{endTime}

    AND check_user_department_id IN

        #{deptId}



    AND (gmt_create_time < #{lastTime} OR (gmt_create_time = #{lastTime} AND id < #{lastId}))

ORDER BY gmt_create_time DESC, id DESC
LIMIT #{pageSize}
